def f(inputs):
    n, w, V = inputs  # Unpacking the input tuple
    cnt = 0
    # Start by initializing the frequency table
    freq = [0] * (w+1)
    for v in V:
        freq[v] += 1
    for v in range(w+1):
        if freq[v] > 0:
            for i in range(v+2, w+2):
                if freq[i] > 0:
                    cnt += freq[v] * freq[i]
    return cnt

# Example usage:
